package com.smartblog.util;
import jakarta.servlet.http.HttpServletRequest; import org.springframework.util.StringUtils;
public class RequestUtil { private RequestUtil(){} public static String getClientIp(HttpServletRequest r){String[] hs={"X-Forwarded-For","X-Real-IP","Proxy-Client-IP","WL-Proxy-Client-IP"}; for(String h:hs){String v=r.getHeader(h); if(StringUtils.hasText(v)&&!"unknown".equalsIgnoreCase(v)) return v.split(",")[0].trim();} return r.getRemoteAddr();} public static String getUserAgent(HttpServletRequest r){String ua=r.getHeader("User-Agent"); if(ua==null) return ""; return ua.length()>500?ua.substring(0,500):ua;} public static String getDeviceName(HttpServletRequest r,String provided){ if(StringUtils.hasText(provided)) return provided.length()>100?provided.substring(0,100):provided; String ua=getUserAgent(r).toLowerCase(); if(ua.contains("windows")) return "Windows Browser"; if(ua.contains("mac os")) return "Mac Browser"; if(ua.contains("android")) return "Android Browser"; if(ua.contains("iphone")||ua.contains("ipad")) return "iOS Browser"; return "Unknown Device";} }
